const allGarages = [{"name": "EasyPark Lot 1 (B5)", "lat": 49.2855, "lon": -123.119, "area": "Downtown", "type": "Garage", "notes": "Underground \u2013 535 Hornby St"}, {"name": "Pacific Centre EasyPark", "lat": 49.283, "lon": -123.1165, "area": "Downtown", "type": "Garage", "notes": "CF Pacific Centre"}, {"name": "EasyPark Lot 19", "lat": 49.2805, "lon": -123.115, "area": "Downtown", "type": "Garage", "notes": "Granville area"}, {"name": "EasyPark Lot 27", "lat": 49.279, "lon": -123.1135, "area": "Downtown", "type": "Garage", "notes": "775 Hamilton St"}, {"name": "Coal Harbour EasyPark", "lat": 49.29, "lon": -123.125, "area": "West End", "type": "Garage", "notes": "Near waterfront"}, {"name": "Stanley Park Pay Lots", "lat": 49.304, "lon": -123.141, "area": "West End", "type": "Lot", "notes": "Park pay parking"}, {"name": "Kitsilano Beach EasyPark", "lat": 49.273, "lon": -123.155, "area": "Kitsilano", "type": "Lot", "notes": "Near beach"}, {"name": "Jericho Beach Parking", "lat": 49.2725, "lon": -123.2, "area": "West Point Grey", "type": "Lot", "notes": "EasyPark managed"}, {"name": "UBC Thunderbird Parkade", "lat": 49.26, "lon": -123.245, "area": "UBC", "type": "Garage", "notes": "Campus parkade"}, {"name": "Mount Pleasant EasyPark", "lat": 49.263, "lon": -123.1, "area": "Mount Pleasant", "type": "Lot", "notes": "Broadway area"}, {"name": "Fairview EasyPark", "lat": 49.265, "lon": -123.13, "area": "Fairview", "type": "Garage", "notes": "Hospital / Broadway"}, {"name": "Strathcona Parking", "lat": 49.278, "lon": -123.09, "area": "Strathcona", "type": "Lot", "notes": "Near Chinatown"}];
const areas = ["Arbutus Ridge", "Downtown", "Fairview", "Grandview-Woodland", "Hastings-Sunrise", "Kensington-Cedar Cottage", "Kerrisdale", "Killarney", "Kitsilano", "Mount Pleasant", "Riley Park", "South Cambie", "Strathcona", "Sunset", "UBC", "West End", "West Point Grey"];
let map, layers = [], userMarker = null, freeRightNowActive = false;
let userLat = null, userLon = null;

function showScreen(name) {
  document.querySelectorAll('.screen').forEach(s => s.classList.remove('active'));
  document.querySelectorAll('nav button').forEach(b => b.classList.remove('active'));
  document.getElementById('screen-' + name).classList.add('active');
  document.getElementById('nav-' + name).classList.add('active');
  if (name === 'map' && !map) initMap();
  if (name === 'garages') renderGarages();
}

function initMap() {
  map = L.map('map').setView([49.2827, -123.1207], 13);
  L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
    attribution: '&copy; OpenStreetMap'
  }).addTo(map);
  updateMap();
}

function haversine(lat1, lon1, lat2, lon2) {
  const R = 6371;
  const dLat = (lat2 - lat1) * Math.PI / 180;
  const dLon = (lon2 - lon1) * Math.PI / 180;
  const a = Math.sin(dLat/2)**2 + Math.cos(lat1*Math.PI/180) * Math.cos(lat2*Math.PI/180) * Math.sin(dLon/2)**2;
  return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));
}

function updateMap() {
  if (!map) return;
  layers.forEach(l => map.removeLayer(l));
  layers = [];
  const area = document.getElementById('areaFilter').value;
  const forceFree = freeRightNowActive;
  let filtered = area === 'All' ? allLines : allLines.filter(p => p.area === area);
  filtered.forEach(p => {
    const color = forceFree ? '#22c55e' : (p.rate_day <= 2 ? '#22c55e' : p.rate_day <= 3.5 ? '#3b82f6' : p.rate_day <= 5 ? '#f97316' : '#ef4444');
    const line = L.polyline(p.coords, {color, weight: 5, opacity: 0.9}).addTo(map);
    line.bindPopup(`<strong>${p.area}</strong><br>Day: $${p.rate_day || 'N/A'}<br><span class="free">Free overnight 10pm–9am</span>`);
    layers.push(line);
  });
  if (!forceFree) {
    let gs = area === 'All' ? allGarages : allGarages.filter(g => g.area === area);
    gs.forEach(g => {
      const m = L.circleMarker([g.lat, g.lon], {radius: 8, fillColor: '#a855f7', color: '#fff', weight: 2, fillOpacity: 0.95}).addTo(map);
      m.bindPopup(`<strong class="garage">${g.name}</strong><br>${g.notes}`);
      layers.push(m);
    });
  }
}

function showNearest() {
  if (!userLat || !userLon) return;
  const list = document.getElementById('nearestList');
  const candidates = [];
  allLines.forEach(p => {
    const midLat = (p.coords[0][0] + p.coords[1][0]) / 2;
    const midLon = (p.coords[0][1] + p.coords[1][1]) / 2;
    const dist = haversine(userLat, userLon, midLat, midLon);
    candidates.push({ type: 'Street', name: p.area, lat: midLat, lon: midLon, dist });
  });
  allGarages.forEach(g => {
    const dist = haversine(userLat, userLon, g.lat, g.lon);
    candidates.push({ type: 'Garage', name: g.name, lat: g.lat, lon: g.lon, dist });
  });
  candidates.sort((a, b) => a.dist - b.dist);
  const top = candidates.slice(0, 5);
  list.innerHTML = '<h3 style="margin:16px 0 8px;">Nearest spots</h3>' + top.map(c => `
    <div class="nearest-item">
      <div><strong>${c.name}</strong> (${c.type})<br><span style="color:var(--muted);font-size:0.85rem;">${c.dist.toFixed(2)} km</span></div>
      <button class="primary" onclick="openDirections(${c.lat}, ${c.lon})">Directions</button>
    </div>
  `).join('');
}

function openDirections(lat, lon) {
  window.open(`https://www.google.com/maps/dir/?api=1&destination=${lat},${lon}`, '_blank');
}

function renderGarages() {
  const list = document.getElementById('garageList');
  list.innerHTML = allGarages.map(g => `
    <div class="card">
      <h3 class="garage" style="margin-top:0;">${g.name}</h3>
      <p style="color:var(--muted); margin:4px 0;">${g.type} · ${g.area}</p>
      <p style="margin:0;">${g.notes}</p>
    </div>
  `).join('');
}

function updateMapSuggestions() {
  const q = document.getElementById('mapSearchBox').value.trim().toLowerCase();
  const box = document.getElementById('mapSuggestions');
  if (!q) { box.style.display = 'none'; return; }
  const matches = areas.filter(a => a.toLowerCase().includes(q));
  if (matches.length === 0) { box.style.display = 'none'; return; }
  box.innerHTML = matches.map(a => `<div class="suggestion" data-area="${a}">${a}</div>`).join('');
  box.style.display = 'block';
  box.querySelectorAll('.suggestion').forEach(el => {
    el.addEventListener('click', () => {
      document.getElementById('mapSearchBox').value = el.dataset.area;
      document.getElementById('areaFilter').value = el.dataset.area;
      box.style.display = 'none';
      updateMap();
    });
  });
}

document.getElementById('areaFilter').addEventListener('change', updateMap);
document.getElementById('freeNowBtn').addEventListener('click', () => {
  freeRightNowActive = !freeRightNowActive;
  document.getElementById('freeNowBtn').textContent = freeRightNowActive ? 'Show all' : 'Free right now';
  updateMap();
});
document.getElementById('locateBtn').addEventListener('click', () => {
  if (!navigator.geolocation) return;
  navigator.geolocation.getCurrentPosition(pos => {
    userLat = pos.coords.latitude;
    userLon = pos.coords.longitude;
    if (userMarker) map.removeLayer(userMarker);
    userMarker = L.circleMarker([userLat, userLon], {radius: 10, fillColor: '#3b82f6', color: '#fff', weight: 3, fillOpacity: 1}).addTo(map).bindPopup('You are here').openPopup();
    map.setView([userLat, userLon], 16);
    document.getElementById('nearestBtn').style.display = 'inline-block';
    showNearest();
  });
});
document.getElementById('nearestBtn').addEventListener('click', showNearest);
document.getElementById('mapSearchBox').addEventListener('input', updateMapSuggestions);
document.getElementById('mapSearchBox').addEventListener('keypress', (e) => {
  if (e.key === 'Enter') {
    const q = document.getElementById('mapSearchBox').value.trim();
    const match = areas.find(a => a.toLowerCase().includes(q.toLowerCase()));
    if (match) {
      document.getElementById('areaFilter').value = match;
      document.getElementById('mapSuggestions').style.display = 'none';
      updateMap();
    }
  }
});
document.addEventListener('click', (e) => {
  if (!e.target.closest('.search-box')) {
    document.getElementById('mapSuggestions').style.display = 'none';
  }
});